using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.EntityFrameworkCore;
using Moq;
using System;
using System.Collections.Generic;

namespace ContosoUniversity.Tests.Helpers
{
    public static class TestHelpers
    {
        public static SchoolContext CreateInMemoryContext(string? dbName = null)
        {
            dbName ??= Guid.NewGuid().ToString();
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;
            return new SchoolContext(options);
        }

        public static void SetupController(Controller controller)
        {
            controller.ControllerContext = new ControllerContext
            {
                HttpContext = new DefaultHttpContext()
            };
            controller.TempData = new TempDataDictionary(
                controller.ControllerContext.HttpContext,
                Mock.Of<ITempDataProvider>());
        }

        /// <summary>
        /// Drains the static NotificationService queue to prevent cross-test interference.
        /// </summary>
        public static void DrainNotificationQueue()
        {
            var svc = new NotificationService();
            while (svc.ReceiveNotification() != null) { }
        }

        public static void SeedStudents(SchoolContext context)
        {
            context.Students.AddRange(
                new Student { ID = 1, FirstMidName = "Carson", LastName = "Alexander", EnrollmentDate = new DateTime(2020, 9, 1) },
                new Student { ID = 2, FirstMidName = "Meredith", LastName = "Alonso", EnrollmentDate = new DateTime(2021, 9, 1) },
                new Student { ID = 3, FirstMidName = "Arturo", LastName = "Anand", EnrollmentDate = new DateTime(2019, 9, 1) }
            );
            context.SaveChanges();
        }

        public static void SeedDepartmentsAndCourses(SchoolContext context)
        {
            var instructor = new Instructor
            {
                ID = 100,
                FirstMidName = "Kim",
                LastName = "Abercrombie",
                HireDate = new DateTime(2000, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };
            context.Instructors.Add(instructor);
            context.SaveChanges();

            var dept = new Department
            {
                DepartmentID = 1,
                Name = "Engineering",
                Budget = 350000,
                StartDate = new DateTime(2007, 9, 1),
                InstructorID = instructor.ID
            };
            context.Departments.Add(dept);
            context.SaveChanges();

            context.Courses.AddRange(
                new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = dept.DepartmentID },
                new Course { CourseID = 4022, Title = "Microeconomics", Credits = 3, DepartmentID = dept.DepartmentID }
            );
            context.SaveChanges();
        }
    }
}

using ContosoUniversity.Models;
using ContosoUniversity.Services;
using ContosoUniversity.Tests.Helpers;
using System;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _sut = new();

        public NotificationServiceTests()
        {
            TestHelpers.DrainNotificationQueue();
        }

        public void Dispose()
        {
            TestHelpers.DrainNotificationQueue();
            _sut.Dispose();
        }

        [Fact]
        public void SendNotification_EnqueuesAndReceiveDequeues()
        {
            _sut.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");

            var result = _sut.ReceiveNotification();

            Assert.NotNull(result);
            Assert.Equal("Student", result.EntityType);
            Assert.Equal("1", result.EntityId);
            Assert.Equal("CREATE", result.Operation);
            Assert.Equal("Admin", result.CreatedBy);
            Assert.False(result.IsRead);
            Assert.Contains("Student 'John Doe'", result.Message);
            Assert.Contains("created", result.Message);
        }

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            var result = _sut.ReceiveNotification();
            Assert.Null(result);
        }

        [Fact]
        public void SendNotification_WithoutUserName_DefaultsToSystem()
        {
            _sut.SendNotification("Course", "42", EntityOperation.UPDATE);

            var result = _sut.ReceiveNotification();

            Assert.NotNull(result);
            Assert.Equal("System", result.CreatedBy);
        }

        [Theory]
        [InlineData(EntityOperation.CREATE, "created")]
        [InlineData(EntityOperation.UPDATE, "updated")]
        [InlineData(EntityOperation.DELETE, "deleted")]
        public void SendNotification_GeneratesCorrectMessage_ForOperation(EntityOperation operation, string expectedVerb)
        {
            _sut.SendNotification("Department", "5", "Math", operation);

            var result = _sut.ReceiveNotification();

            Assert.NotNull(result);
            Assert.Contains(expectedVerb, result.Message);
            Assert.Contains("Department 'Math'", result.Message);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesIdInMessage()
        {
            _sut.SendNotification("Instructor", "99", EntityOperation.CREATE);

            var result = _sut.ReceiveNotification();

            Assert.NotNull(result);
            Assert.Contains("Instructor (ID: 99)", result.Message);
        }

        [Fact]
        public void SendNotification_MultipleMessages_DequeuedInOrder()
        {
            _sut.SendNotification("A", "1", EntityOperation.CREATE);
            _sut.SendNotification("B", "2", EntityOperation.UPDATE);
            _sut.SendNotification("C", "3", EntityOperation.DELETE);

            Assert.Equal("A", _sut.ReceiveNotification()!.EntityType);
            Assert.Equal("B", _sut.ReceiveNotification()!.EntityType);
            Assert.Equal("C", _sut.ReceiveNotification()!.EntityType);
            Assert.Null(_sut.ReceiveNotification());
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // MarkAsRead is a no-op for in-memory implementation
            var exception = Record.Exception(() => _sut.MarkAsRead(42));
            Assert.Null(exception);
        }

        [Fact]
        public void SendNotification_OverMaxQueue_DoesNotGrowUnbounded()
        {
            // Send more than _maxQueueLength (500) notifications
            for (int i = 0; i < 510; i++)
            {
                _sut.SendNotification("Entity", i.ToString(), EntityOperation.CREATE);
            }

            // Drain and count - should be at most 500
            int count = 0;
            while (_sut.ReceiveNotification() != null) count++;
            Assert.True(count <= 500, $"Queue had {count} items, expected <= 500");
        }

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            var svc = new NotificationService();
            var exception = Record.Exception(() => svc.Dispose());
            Assert.Null(exception);
        }
    }
}

using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class PaginatedListTests
    {
        [Fact]
        public void Create_ReturnsCorrectPage()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 10);

            Assert.Equal(10, result.Count);
            Assert.Equal(11, result.First());
            Assert.Equal(20, result.Last());
            Assert.Equal(2, result.PageIndex);
            Assert.Equal(3, result.TotalPages);
        }

        [Fact]
        public void Create_FirstPage_HasNextButNoPrevious()
        {
            var source = Enumerable.Range(1, 20).AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

            Assert.False(result.HasPreviousPage);
            Assert.True(result.HasNextPage);
        }

        [Fact]
        public void Create_LastPage_HasPreviousButNoNext()
        {
            var source = Enumerable.Range(1, 20).AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 10);

            Assert.True(result.HasPreviousPage);
            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void Create_SinglePage_HasNeitherPreviousNorNext()
        {
            var source = Enumerable.Range(1, 5).AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

            Assert.False(result.HasPreviousPage);
            Assert.False(result.HasNextPage);
            Assert.Equal(1, result.TotalPages);
        }

        [Fact]
        public void Create_EmptySource_ReturnsEmptyList()
        {
            var source = Enumerable.Empty<int>().AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

            Assert.Empty(result);
            Assert.Equal(0, result.TotalPages);
        }

        [Fact]
        public void Create_LastPagePartial_ContainsRemainingItems()
        {
            var source = Enumerable.Range(1, 15).AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 10);

            Assert.Equal(5, result.Count);
            Assert.Equal(11, result.First());
            Assert.Equal(15, result.Last());
        }

        [Theory]
        [InlineData(1, 10, 1)]
        [InlineData(10, 10, 1)]
        [InlineData(11, 10, 2)]
        [InlineData(100, 10, 10)]
        [InlineData(101, 10, 11)]
        public void TotalPages_CalculatedCorrectly(int totalItems, int pageSize, int expectedPages)
        {
            var source = Enumerable.Range(1, totalItems).AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: pageSize);

            Assert.Equal(expectedPages, result.TotalPages);
        }
    }
}

