namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;

        public NotificationsControllerTests()
        {
            TestHelpers.DrainNotificationQueue();
            _context = TestHelpers.CreateInMemoryContext();
            _controller = new NotificationsController(_context);
            TestHelpers.SetupController(_controller);
        }

        public void Dispose()
        {
            TestHelpers.DrainNotificationQueue();
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void GetNotifications_EmptyQueue_ReturnsSuccessWithZeroCount()
        {
            var result = _controller.GetNotifications();

            Assert.NotNull(result);
            var json = result.Value as dynamic;
            Assert.NotNull(json);
        }

        [Fact]
        public void GetNotifications_WithNotifications_ReturnsNotifications()
        {
            // Enqueue some notifications via the service
            var svc = new NotificationService();
            svc.SendNotification("Student", "1", "Alice", EntityOperation.CREATE);
            svc.SendNotification("Course", "2", "Math", EntityOperation.UPDATE);

            var result = _controller.GetNotifications();

            Assert.NotNull(result);
            // Verify the result is a JsonResult (the exact shape depends on anonymous type)
            Assert.IsType<JsonResult>(result);
        }

        [Fact]
        public void GetNotifications_LimitsTo10Notifications()
        {
            var svc = new NotificationService();
            for (int i = 0; i < 15; i++)
            {
                svc.SendNotification("Entity", i.ToString(), EntityOperation.CREATE);
            }

            var result = _controller.GetNotifications();

            Assert.IsType<JsonResult>(result);
            // After GetNotifications, at most 10 were consumed, 5 remain
            int remaining = 0;
            while (svc.ReceiveNotification() != null) remaining++;
            Assert.Equal(5, remaining);
        }

        [Fact]
        public void MarkAsRead_ReturnsSuccess()
        {
            var result = _controller.MarkAsRead(1);

            Assert.IsType<JsonResult>(result);
        }

        [Fact]
        public void Index_ReturnsView()
        {
            var result = _controller.Index();

            Assert.IsType<ViewResult>(result);
        }
    }
}

using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class DbInitializerTests : IDisposable
    {
        private readonly SchoolContext _context;

        public DbInitializerTests()
        {
            _context = TestHelpers.CreateInMemoryContext();
        }

        public void Dispose()
        {
            _context.Dispose();
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsAllEntities()
        {
            DbInitializer.Initialize(_context);

            Assert.Equal(8, _context.Students.Count());
            Assert.Equal(5, _context.Instructors.Count());
            Assert.Equal(4, _context.Departments.Count());
            Assert.Equal(7, _context.Courses.Count());
            Assert.Equal(3, _context.OfficeAssignments.Count());
            Assert.Equal(8, _context.CourseAssignments.Count());
            Assert.True(_context.Enrollments.Count() >= 11);
        }

        [Fact]
        public void Initialize_ExistingData_SkipsSeeding()
        {
            // Pre-seed with one student
            _context.Students.Add(new Student
            {
                FirstMidName = "Existing",
                LastName = "Student",
                EnrollmentDate = DateTime.Now
            });
            _context.SaveChanges();

            DbInitializer.Initialize(_context);

            // Should still have only the one pre-seeded student
            Assert.Single(_context.Students);
            Assert.Equal("Student", _context.Students.First().LastName);
        }

        [Fact]
        public void Initialize_SeedsCorrectStudentNames()
        {
            DbInitializer.Initialize(_context);

            var lastNames = _context.Students.Select(s => s.LastName).OrderBy(n => n).ToList();
            Assert.Contains("Alexander", lastNames);
            Assert.Contains("Alonso", lastNames);
            Assert.Contains("Olivetto", lastNames);
        }

        [Fact]
        public void Initialize_SeedsCoursesWithDepartments()
        {
            DbInitializer.Initialize(_context);

            var chemistry = _context.Courses.Single(c => c.Title == "Chemistry");
            var dept = _context.Departments.Find(chemistry.DepartmentID);
            Assert.NotNull(dept);
            Assert.Equal("Engineering", dept.Name);
        }

        [Fact]
        public void Initialize_SeedsInstructorsWithOfficeAssignments()
        {
            DbInitializer.Initialize(_context);

            var officeAssignments = _context.OfficeAssignments.ToList();
            Assert.Equal(3, officeAssignments.Count);
            Assert.Contains(officeAssignments, oa => oa.Location == "Smith 17");
        }

        [Fact]
        public void Initialize_SeedsEnrollmentsWithGrades()
        {
            DbInitializer.Initialize(_context);

            var enrollmentsWithGrades = _context.Enrollments.Where(e => e.Grade != null).ToList();
            Assert.True(enrollmentsWithGrades.Count >= 10);

            // Check Alexander has an A in Chemistry
            var alexanderId = _context.Students.Single(s => s.LastName == "Alexander").ID;
            var chemistryEnrollment = _context.Enrollments.Single(e => e.StudentID == alexanderId && e.CourseID == 1050);
            Assert.Equal(Grade.A, chemistryEnrollment.Grade);
        }

        [Fact]
        public void Initialize_SeedsDepartmentsWithAdministrators()
        {
            DbInitializer.Initialize(_context);

            var english = _context.Departments.Single(d => d.Name == "English");
            Assert.NotNull(english.InstructorID);
            var admin = _context.Instructors.Find(english.InstructorID);
            Assert.Equal("Abercrombie", admin!.LastName);
        }
    }
}

using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class SchoolContextTests : IDisposable
    {
        private readonly SchoolContext _context;

        public SchoolContextTests()
        {
            _context = TestHelpers.CreateInMemoryContext();
        }

        public void Dispose()
        {
            _context.Dispose();
        }

        [Fact]
        public void CanAddAndRetrieveStudent()
        {
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = new DateTime(2023, 1, 1)
            };
            _context.Students.Add(student);
            _context.SaveChanges();

            var retrieved = _context.Students.Single(s => s.LastName == "Student");
            Assert.Equal("Test", retrieved.FirstMidName);
            Assert.Equal(new DateTime(2023, 1, 1), retrieved.EnrollmentDate);
        }

        [Fact]
        public void CanAddAndRetrieveInstructor()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Jane",
                LastName = "Doe",
                HireDate = new DateTime(2020, 6, 15),
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var retrieved = _context.Instructors.Single(i => i.LastName == "Doe");
            Assert.Equal("Jane", retrieved.FirstMidName);
        }

        [Fact]
        public void CourseAssignment_HasCompositeKey()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Key",
                LastName = "Test",
                HireDate = DateTime.Now,
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var course = new Course { CourseID = 9001, Title = "Composite", Credits = 3, DepartmentID = 0 };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var assignment = new CourseAssignment { InstructorID = instructor.ID, CourseID = 9001 };
            _context.CourseAssignments.Add(assignment);
            _context.SaveChanges();

            var retrieved = _context.CourseAssignments.Find(9001, instructor.ID);
            Assert.NotNull(retrieved);
        }

        [Fact]
        public void Enrollment_RelationshipsWork()
        {
            var student = new Student { FirstMidName = "Enroll", LastName = "Test", EnrollmentDate = DateTime.Now };
            _context.Students.Add(student);
            var course = new Course { CourseID = 9002, Title = "EnrollCourse", Credits = 3, DepartmentID = 0 };
            _context.Courses.Add(course);
            _context.SaveChanges();

            _context.Enrollments.Add(new Enrollment { StudentID = student.ID, CourseID = 9002, Grade = Grade.B });
            _context.SaveChanges();

            var enrollment = _context.Enrollments
                .Include(e => e.Student)
                .Include(e => e.Course)
                .Single(e => e.CourseID == 9002);

            Assert.Equal("Test", enrollment.Student.LastName);
            Assert.Equal("EnrollCourse", enrollment.Course.Title);
            Assert.Equal(Grade.B, enrollment.Grade);
        }

        [Fact]
        public void Person_FullName_ConcatenatesLastAndFirst()
        {
            var student = new Student { FirstMidName = "John", LastName = "Smith", EnrollmentDate = DateTime.Now };
            Assert.Equal("Smith, John", student.FullName);
        }

        [Fact]
        public void Department_CanHaveNullAdministrator()
        {
            var dept = new Department
            {
                Name = "NoAdmin",
                Budget = 50000,
                StartDate = DateTime.Now,
                InstructorID = null
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var retrieved = _context.Departments.Single(d => d.Name == "NoAdmin");
            Assert.Null(retrieved.InstructorID);
        }

        [Fact]
        public void Notification_CanBeAddedAndRetrieved()
        {
            var notification = new Notification
            {
                EntityType = "Student",
                EntityId = "1",
                Operation = "CREATE",
                Message = "Test notification",
                CreatedAt = DateTime.Now,
                CreatedBy = "Test",
                IsRead = false
            };
            _context.Notifications.Add(notification);
            _context.SaveChanges();

            var retrieved = _context.Notifications.Single();
            Assert.Equal("Student", retrieved.EntityType);
            Assert.Equal("Test notification", retrieved.Message);
            Assert.False(retrieved.IsRead);
        }

        [Fact]
        public void ErrorViewModel_ShowRequestId_ReturnsTrueWhenSet()
        {
            var model = new ErrorViewModel { RequestId = "abc123" };
            Assert.True(model.ShowRequestId);
        }

        [Fact]
        public void ErrorViewModel_ShowRequestId_ReturnsFalseWhenEmpty()
        {
            var model = new ErrorViewModel { RequestId = "" };
            Assert.False(model.ShowRequestId);

            var model2 = new ErrorViewModel { RequestId = null };
            Assert.False(model2.ShowRequestId);
        }
    }
}

