        [Fact]
        public void CanAddAndRetrieveStudent()
        {
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = new DateTime(2023, 1, 1)
            };
            _context.Students.Add(student);
            _context.SaveChanges();

            var retrieved = _context.Students.Single(s => s.LastName == "Student");
            Assert.Equal("Test", retrieved.FirstMidName);
            Assert.Equal(new DateTime(2023, 1, 1), retrieved.EnrollmentDate);
        }

        [Fact]
        public void CanAddAndRetrieveInstructor()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Jane",
                LastName = "Doe",
                HireDate = new DateTime(2020, 6, 15),
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var retrieved = _context.Instructors.Single(i => i.LastName == "Doe");
            Assert.Equal("Jane", retrieved.FirstMidName);
        }

        [Fact]
        public void CourseAssignment_HasCompositeKey()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Key",
                LastName = "Test",
                HireDate = DateTime.Now,
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var course = new Course { CourseID = 9001, Title = "Composite", Credits = 3, DepartmentID = 0 };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var assignment = new CourseAssignment { InstructorID = instructor.ID, CourseID = 9001 };
            _context.CourseAssignments.Add(assignment);
            _context.SaveChanges();

            var retrieved = _context.CourseAssignments.Find(9001, instructor.ID);
            Assert.NotNull(retrieved);
        }

        [Fact]
        public void Enrollment_RelationshipsWork()
        {
            var student = new Student { FirstMidName = "Enroll", LastName = "Test", EnrollmentDate = DateTime.Now };
            _context.Students.Add(student);
            var course = new Course { CourseID = 9002, Title = "EnrollCourse", Credits = 3, DepartmentID = 0 };
            _context.Courses.Add(course);
            _context.SaveChanges();

            _context.Enrollments.Add(new Enrollment { StudentID = student.ID, CourseID = 9002, Grade = Grade.B });
            _context.SaveChanges();

            var enrollment = _context.Enrollments
                .Include(e => e.Student)
                .Include(e => e.Course)
                .Single(e => e.CourseID == 9002);

            Assert.Equal("Test", enrollment.Student.LastName);
            Assert.Equal("EnrollCourse", enrollment.Course.Title);
            Assert.Equal(Grade.B, enrollment.Grade);
