using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class DepartmentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly DepartmentsController _controller;

        public DepartmentsControllerTests()
        {
            TestHelpers.DrainNotificationQueue();
            _context = TestHelpers.CreateInMemoryContext();
            SeedData();
            _controller = new DepartmentsController(_context);
            TestHelpers.SetupController(_controller);
        }

        private void SeedData()
        {
            var instructor = new Instructor
            {
                ID = 1,
                FirstMidName = "Kim",
                LastName = "Abercrombie",
                HireDate = new DateTime(2000, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            _context.Departments.AddRange(
                new Department { DepartmentID = 1, Name = "Engineering", Budget = 350000, StartDate = new DateTime(2007, 9, 1), InstructorID = 1 },
                new Department { DepartmentID = 2, Name = "Mathematics", Budget = 100000, StartDate = new DateTime(2007, 9, 1), InstructorID = 1 }
            );
            _context.SaveChanges();
        }

        public void Dispose()
        {
            TestHelpers.DrainNotificationQueue();
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Index_ReturnsAllDepartments()
        {
            var result = _controller.Index() as ViewResult;

            Assert.NotNull(result);
            var departments = Assert.IsAssignableFrom<List<Department>>(result.Model);
            Assert.Equal(2, departments.Count);
        }

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_NotFound_ReturnsNotFound()
        {
            var result = _controller.Details(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Details_ValidId_ReturnsDepartment()
        {
            var result = _controller.Details(1) as ViewResult;

            Assert.NotNull(result);
            var dept = Assert.IsType<Department>(result.Model);
            Assert.Equal("Engineering", dept.Name);
        }

        [Fact]
        public void Create_GET_ReturnsViewWithInstructorList()
        {
            var result = _controller.Create() as ViewResult;

            Assert.NotNull(result);
            Assert.NotNull(_controller.ViewBag.InstructorID);
        }

        [Fact]
        public void Create_POST_ValidDepartment_RedirectsToIndex()
        {
            var dept = new Department
            {
                Name = "Physics",
                Budget = 200000,
                StartDate = new DateTime(2023, 1, 1),
                InstructorID = 1
            };

            var result = _controller.Create(dept);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Equal(3, _context.Departments.Count());
        }

        [Fact]
        public void Create_POST_InvalidModelState_ReturnsView()
        {
            _controller.ModelState.AddModelError("Name", "Required");
            var dept = new Department { Name = "", Budget = 100, StartDate = DateTime.Now, InstructorID = 1 };

            var result = _controller.Create(dept) as ViewResult;

            Assert.NotNull(result);
            Assert.Equal(dept, result.Model);
        }

        [Fact]
        public void Edit_GET_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit((int?)null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_GET_NotFound_ReturnsNotFound()
        {
            var result = _controller.Edit(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_GET_ValidId_ReturnsDepartmentView()
        {
            var result = _controller.Edit(1) as ViewResult;

            Assert.NotNull(result);
            var dept = Assert.IsType<Department>(result.Model);
            Assert.Equal("Engineering", dept.Name);
        }

        [Fact]
        public void Edit_POST_ValidDepartment_RedirectsToIndex()
        {
            var dept = new Department
            {
                DepartmentID = 1,
                Name = "Engineering Updated",
                Budget = 400000,
                StartDate = new DateTime(2007, 9, 1),
                InstructorID = 1
            };

            var tracked = _context.Departments.Local.FirstOrDefault(d => d.DepartmentID == 1);
            if (tracked != null)
                _context.Entry(tracked).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var result = _controller.Edit(dept);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Edit_POST_InvalidModelState_ReturnsView()
        {
            _controller.ModelState.AddModelError("Name", "Required");
            var dept = new Department { DepartmentID = 1, Name = "", Budget = 100, StartDate = DateTime.Now, InstructorID = 1 };

            var result = _controller.Edit(dept) as ViewResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void Delete_GET_NullId_ReturnsBadRequest()
        {
            var result = _controller.Delete(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_GET_NotFound_ReturnsNotFound()
        {
            var result = _controller.Delete(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Delete_GET_ValidId_ReturnsDepartmentView()
        {
            var result = _controller.Delete(1) as ViewResult;

            Assert.NotNull(result);
            var dept = Assert.IsType<Department>(result.Model);
            Assert.Equal("Engineering", dept.Name);
        }

        [Fact]
        public void DeleteConfirmed_RemovesDepartmentAndRedirects()
        {
            var result = _controller.DeleteConfirmed(1);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Null(_context.Departments.Find(1));
        }

        [Fact]
        public void Create_POST_ValidDepartment_SendsNotification()
        {
            var dept = new Department
            {
                Name = "History",
                Budget = 100000,
                StartDate = new DateTime(2023, 1, 1),
                InstructorID = 1
            };

            _controller.Create(dept);

            var notification = new ContosoUniversity.Services.NotificationService().ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Department", notification.EntityType);
            Assert.Contains("created", notification.Message);
        }
    }
}

