using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class InstructorsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly InstructorsController _controller;

        public InstructorsControllerTests()
        {
            TestHelpers.DrainNotificationQueue();
            _context = TestHelpers.CreateInMemoryContext();
            SeedData();
            _controller = new InstructorsController(_context);
            TestHelpers.SetupController(_controller);
        }

        private void SeedData()
        {
            var dept = new Department
            {
                DepartmentID = 1,
                Name = "Engineering",
                Budget = 350000,
                StartDate = new DateTime(2007, 9, 1)
            };
            _context.Departments.Add(dept);

            var course1 = new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = 1 };
            var course2 = new Course { CourseID = 4022, Title = "Microeconomics", Credits = 3, DepartmentID = 1 };
            _context.Courses.AddRange(course1, course2);
            _context.SaveChanges();

            var instructor = new Instructor
            {
                ID = 1,
                FirstMidName = "Kim",
                LastName = "Abercrombie",
                HireDate = new DateTime(2000, 1, 1),
                CourseAssignments = new List<CourseAssignment>
                {
                    new CourseAssignment { CourseID = 1050, InstructorID = 1 }
                },
                OfficeAssignment = new OfficeAssignment { InstructorID = 1, Location = "Smith 17" }
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            // Link department to instructor
            dept.InstructorID = 1;
            _context.SaveChanges();
        }

        public void Dispose()
        {
            TestHelpers.DrainNotificationQueue();
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Index_NoSelection_ReturnsInstructorsViewModel()
        {
            var result = _controller.Index(null, null) as ViewResult;

            Assert.NotNull(result);
            var viewModel = Assert.IsType<InstructorIndexData>(result.Model);
            Assert.Single(viewModel.Instructors);
        }

        [Fact]
        public void Index_WithInstructorId_PopulatesCourses()
        {
            var result = _controller.Index(1, null) as ViewResult;

            Assert.NotNull(result);
            var viewModel = Assert.IsType<InstructorIndexData>(result.Model);
            Assert.NotNull(viewModel.Courses);
            Assert.Single(viewModel.Courses);
            Assert.Equal("Chemistry", viewModel.Courses.First().Title);
        }

        [Fact]
        public void Index_WithCourseId_PopulatesEnrollments()
        {
            // Add enrollment
            var student = new Student { ID = 10, FirstMidName = "Test", LastName = "Student", EnrollmentDate = DateTime.Now };
            _context.Students.Add(student);
            _context.Enrollments.Add(new Enrollment { StudentID = 10, CourseID = 1050, Grade = Grade.A });
            _context.SaveChanges();

            var result = _controller.Index(1, 1050) as ViewResult;

            Assert.NotNull(result);
            var viewModel = Assert.IsType<InstructorIndexData>(result.Model);
            Assert.NotNull(viewModel.Enrollments);
            Assert.Single(viewModel.Enrollments);
        }

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_NotFound_ReturnsNotFound()
        {
            var result = _controller.Details(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Details_ValidId_ReturnsInstructor()
        {
            var result = _controller.Details(1) as ViewResult;

            Assert.NotNull(result);
            var instructor = Assert.IsType<Instructor>(result.Model);
            Assert.Equal("Abercrombie", instructor.LastName);
        }

        [Fact]
        public void Create_GET_ReturnsViewWithCourseData()
        {
            var result = _controller.Create() as ViewResult;

            Assert.NotNull(result);
            var instructor = Assert.IsType<Instructor>(result.Model);
            Assert.NotNull(instructor.CourseAssignments);
            Assert.NotNull(_controller.ViewBag.Courses);
        }

        [Fact]
        public void Create_POST_ValidInstructor_RedirectsToIndex()
        {
            var instructor = new Instructor
            {
                FirstMidName = "New",
                LastName = "Instructor",
                HireDate = new DateTime(2023, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = _controller.Create(instructor, null);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Create_POST_WithSelectedCourses_AddsCourseAssignments()
        {
            var instructor = new Instructor
            {
                FirstMidName = "CourseAssign",
                LastName = "Test",
                HireDate = new DateTime(2023, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = _controller.Create(instructor, new[] { "1050", "4022" });

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);

            var saved = _context.Instructors
                .Where(i => i.LastName == "Test")
                .Select(i => i.CourseAssignments.Count)
                .Single();
            Assert.Equal(2, saved);
        }

        [Fact]
        public void Create_POST_InvalidModelState_ReturnsView()
        {
            _controller.ModelState.AddModelError("LastName", "Required");
            var instructor = new Instructor
            {
                FirstMidName = "Bad",
                LastName = "",
                HireDate = DateTime.Now,
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = _controller.Create(instructor, null) as ViewResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void Delete_GET_NullId_ReturnsBadRequest()
        {
            var result = _controller.Delete(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_GET_NotFound_ReturnsNotFound()
        {
            var result = _controller.Delete(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Delete_GET_ValidId_ReturnsInstructorView()
        {
            var result = _controller.Delete(1) as ViewResult;

            Assert.NotNull(result);
            var instructor = Assert.IsType<Instructor>(result.Model);
            Assert.Equal("Abercrombie", instructor.LastName);
        }

        [Fact]
        public void DeleteConfirmed_RemovesInstructorAndRedirects()
        {
            var result = _controller.DeleteConfirmed(1);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Null(_context.Instructors.Find(1));
        }

        [Fact]
        public void DeleteConfirmed_NullsDepartmentAdministrator()
        {
            _controller.DeleteConfirmed(1);

            var dept = _context.Departments.Find(1);
            Assert.NotNull(dept);
            Assert.Null(dept.InstructorID);
        }

        [Fact]
        public void Edit_GET_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit((int?)null) as StatusCodeResult;

            Assert.NotNull(result);
            Assert.Equal(400, result.StatusCode);
        }

        [Fact]
        public void Edit_GET_ValidId_ReturnsInstructorView()
        {
            var result = _controller.Edit(1) as ViewResult;

            Assert.NotNull(result);
            Assert.NotNull(_controller.ViewBag.Courses);
        }
    }
}

