using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class DbInitializerTests : IDisposable
    {
        private readonly SchoolContext _context;

        public DbInitializerTests()
        {
            _context = TestHelpers.CreateInMemoryContext();
        }

        public void Dispose()
        {
            _context.Dispose();
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsAllEntities()
        {
            DbInitializer.Initialize(_context);

            Assert.Equal(8, _context.Students.Count());
            Assert.Equal(5, _context.Instructors.Count());
            Assert.Equal(4, _context.Departments.Count());
            Assert.Equal(7, _context.Courses.Count());
            Assert.Equal(3, _context.OfficeAssignments.Count());
            Assert.Equal(8, _context.CourseAssignments.Count());
            Assert.True(_context.Enrollments.Count() >= 11);
        }

        [Fact]
        public void Initialize_ExistingData_SkipsSeeding()
        {
            // Pre-seed with one student
            _context.Students.Add(new Student
            {
                FirstMidName = "Existing",
                LastName = "Student",
                EnrollmentDate = DateTime.Now
            });
            _context.SaveChanges();

            DbInitializer.Initialize(_context);

            // Should still have only the one pre-seeded student
            Assert.Single(_context.Students);
            Assert.Equal("Student", _context.Students.First().LastName);
        }

        [Fact]
        public void Initialize_SeedsCorrectStudentNames()
        {
            DbInitializer.Initialize(_context);

            var lastNames = _context.Students.Select(s => s.LastName).OrderBy(n => n).ToList();
            Assert.Contains("Alexander", lastNames);
            Assert.Contains("Alonso", lastNames);
            Assert.Contains("Olivetto", lastNames);
        }

        [Fact]
        public void Initialize_SeedsCoursesWithDepartments()
        {
            DbInitializer.Initialize(_context);

            var chemistry = _context.Courses.Single(c => c.Title == "Chemistry");
            var dept = _context.Departments.Find(chemistry.DepartmentID);
            Assert.NotNull(dept);
            Assert.Equal("Engineering", dept.Name);
        }

        [Fact]
        public void Initialize_SeedsInstructorsWithOfficeAssignments()
        {
            DbInitializer.Initialize(_context);

            var officeAssignments = _context.OfficeAssignments.ToList();
            Assert.Equal(3, officeAssignments.Count);
            Assert.Contains(officeAssignments, oa => oa.Location == "Smith 17");
        }

        [Fact]
        public void Initialize_SeedsEnrollmentsWithGrades()
        {
            DbInitializer.Initialize(_context);

            var enrollmentsWithGrades = _context.Enrollments.Where(e => e.Grade != null).ToList();
            Assert.True(enrollmentsWithGrades.Count >= 10);

            // Check Alexander has an A in Chemistry
            var alexanderId = _context.Students.Single(s => s.LastName == "Alexander").ID;
            var chemistryEnrollment = _context.Enrollments.Single(e => e.StudentID == alexanderId && e.CourseID == 1050);
            Assert.Equal(Grade.A, chemistryEnrollment.Grade);
        }

        [Fact]
        public void Initialize_SeedsDepartmentsWithAdministrators()
        {
            DbInitializer.Initialize(_context);

            var english = _context.Departments.Single(d => d.Name == "English");
            Assert.NotNull(english.InstructorID);
            var admin = _context.Instructors.Find(english.InstructorID);
            Assert.Equal("Abercrombie", admin!.LastName);
        }
    }
}

